/* Engine adapter — the UI talks only to this file.
 *
 * It prefers the Rust/WASM engine generated by wasm-pack into ./wasm/
 * (root script: `pnpm build:engine`), following docs/ENGINE_API.md:
 *   compress_image(input: Uint8Array, options_json: string): Uint8Array
 *   last_result_json(): string
 *
 * If the WASM module is missing or fails to load, it transparently falls
 * back to the JS Canvas implementation in ./fallback.ts so the app keeps
 * working. The returned `engine` field says which one actually ran. */

import { compressWithFallback } from './fallback'
import type { CompressedOutput, CompressOptions } from './types'

export type { CompressOptions, CompressResult, CompressedOutput } from './types'
export type { EngineMode, EngineFormat, OutputFormat } from './types'

interface WasmEngineModule {
  default?: (input?: unknown) => Promise<unknown>
  compress_image?: (input: Uint8Array, optionsJson: string) => Uint8Array
  last_result_json?: () => string
}

let wasmModulePromise: Promise<WasmEngineModule | null> | null = null

function loadWasmModule(): Promise<WasmEngineModule | null> {
  if (!wasmModulePromise) {
    wasmModulePromise = (async () => {
      try {
        // Whatever entry file wasm-pack generated in ./wasm/ (none yet on a
        // fresh checkout — the glob is simply empty and we fall back).
        const candidates = import.meta.glob('./wasm/*.js')
        for (const path of Object.keys(candidates)) {
          if (path.endsWith('.d.ts')) continue
          const mod = (await candidates[path]()) as WasmEngineModule
          if (typeof mod.compress_image !== 'function') continue
          if (typeof mod.default === 'function') await mod.default()
          return mod
        }
      } catch (err) {
        console.warn('[fotmio] WASM engine failed to load, using fallback.', err)
      }
      return null
    })()
  }
  return wasmModulePromise
}

/** 'wasm' when the Rust engine is available, otherwise 'fallback'. */
export async function detectEngine(): Promise<'wasm' | 'fallback'> {
  return (await loadWasmModule()) ? 'wasm' : 'fallback'
}

export async function compressImage(
  input: Uint8Array,
  inputMime: string,
  options: CompressOptions,
): Promise<CompressedOutput> {
  const wasm = await loadWasmModule()
  if (wasm?.compress_image) {
    try {
      const data = wasm.compress_image(input, JSON.stringify(options))
      if (typeof wasm.last_result_json !== 'function') {
        throw new Error('WASM engine is missing last_result_json().')
      }
      const meta = JSON.parse(wasm.last_result_json())
      return { data, meta, engine: 'wasm' }
    } catch (err) {
      console.warn('[fotmio] WASM compress failed, using fallback.', err)
    }
  }
  return compressWithFallback(input, inputMime, options)
}
